use std::fs;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct Sheet {
    pub raw: String,
    pub rank: u8,
    pub valid: bool,
}

pub fn fold(s: &str) -> String {
    s.trim().to_ascii_lowercase().replace('-', "_")
}

pub fn desc_dir() -> PathBuf {
    PathBuf::from("/app/sanitdesc")
}

pub fn load_glob() -> Vec<Sheet> {
    let mut paths: Vec<PathBuf> = match fs::read_dir(desc_dir()) {
        Ok(rd) => rd.filter_map(|e| e.ok()).map(|e| e.path()).collect(),
        Err(_) => Vec::new(),
    };
    paths.retain(|p| p.extension().and_then(|s| s.to_str()) == Some("kind"));
    paths.sort();
    paths.into_iter().map(|p| parse_sheet(&p)).collect()
}

fn parse_sheet(p: &Path) -> Sheet {
    let t = match fs::read_to_string(p) {
        Ok(t) => t,
        Err(_) => return Sheet { raw: String::new(), rank: 0, valid: false },
    };
    let mut raw: Option<String> = None;
    let mut rank: Option<u8> = None;
    let mut saw_rank = false;
    let mut valid = true;
    for line in t.lines().map(str::trim).filter(|l| !l.is_empty()) {
        let mut fields = line.split_whitespace();
        match fields.next() {
            Some("KIND") if raw.is_none() && !saw_rank => {
                let value = fields.collect::<Vec<_>>().join(" ");
                if value.is_empty() { valid = false; } else { raw = Some(value); }
            }
            Some("RANK") if raw.is_some() && rank.is_none() => {
                saw_rank = true;
                let values: Vec<_> = fields.collect();
                if values.len() != 1 { valid = false; }
                rank = values.first().and_then(|v| v.parse::<u8>().ok());
                if rank.map_or(true, |r| r > 9) { valid = false; }
            }
            _ => valid = false,
        }
    }
    let valid = valid && raw.is_some() && rank.is_some();
    Sheet { raw: raw.unwrap_or_default(), rank: rank.unwrap_or(0), valid }
}

pub fn put_rec(buf: &mut Vec<u8>, name: &str, rank: u8) -> bool {
    let b = name.as_bytes();
    let n = match u16::try_from(b.len()) { Ok(n) => n, Err(_) => return false };
    buf.extend_from_slice(&n.to_be_bytes());
    buf.extend_from_slice(b);
    buf.push(rank);
    true
}

pub fn parse_recs(bytes: &[u8]) -> Option<Vec<(String, u8)>> {
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if i + 2 > bytes.len() { return None; }
        let n = u16::from_be_bytes([bytes[i], bytes[i + 1]]) as usize;
        i += 2;
        if i.checked_add(n + 1).map_or(true, |end| end > bytes.len()) { return None; }
        let name = std::str::from_utf8(&bytes[i..i + n]).ok()?.to_string();
        i += n;
        let rank = bytes[i];
        i += 1;
        if rank > 9 { return None; }
        out.push((name, rank));
    }
    Some(out)
}
