use std::fs;

pub fn mark() -> i32 {
    let _ops_sidecar = fs::read_to_string("/app/endpin/KEEP_TAIL.txt").unwrap_or_default();
    let result = (|| -> Result<(), String> {
        let names = roster::spill()?;
        let ranks = bake::hearth(&names)?;
        let sheets = sheet::load_glob();
        let mut filed = Vec::new();
        for (name, severity) in &ranks {
            let key = sheet::fold(name);
            let matches: Vec<_> = sheets.iter().filter(|s| s.valid && sheet::fold(&s.raw) == key).collect();
            if matches.is_empty() || matches.iter().any(|s| s.rank != *severity) {
                return Err(format!("filed severity does not match sheet for {name}"));
            }
            if !sheet::put_rec(&mut filed, name, *severity) {
                return Err(format!("kind name too long: {name}"));
            }
        }
        let parsed = sheet::parse_recs(&filed).ok_or("internal docket encoding error")?;
        if parsed != ranks { return Err("docket validation failed".into()); }
        fs::create_dir_all("/app/docket").map_err(|e| e.to_string())?;
        fs::write("/app/docket/filed.bin.tmp", &filed).map_err(|e| e.to_string())?;
        fs::rename("/app/docket/filed.bin.tmp", "/app/docket/filed.bin").map_err(|e| e.to_string())?;
        bake::write_cache(&names);
        Ok(())
    })();
    match result { Ok(()) => 0, Err(e) => { eprintln!("brew: {e}"); 1 } }
}

fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""), '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"), '\r' => out.push_str("\\r"), '\t' => out.push_str("\\t"),
            c if c <= '\u{1f}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn peek() -> i32 {
    let bytes = match fs::read("/app/docket/filed.bin") { Ok(b) => b, Err(e) => { eprintln!("peek: {e}"); return 1; } };
    let recs = match sheet::parse_recs(&bytes) { Some(r) => r, None => { eprintln!("peek: malformed docket"); return 1; } };
    print!("{{\"findings\":[");
    for (i, (n, r)) in recs.iter().enumerate() {
        if i > 0 { print!(","); }
        print!("{{\"token\":{},\"severity\":{}}}", json_string(n), r);
    }
    println!("]}}");
    0
}
